from pathlib import Path
import re

path = Path('/home/ubuntu/devora-frontend/client/src/pages/Home.tsx')
text = path.read_text()
pattern = r'function MemberStatus\([\s\S]*?\nfunction KnowledgeGapReview'
replacement = '''function MemberStatus({ focus, setFocus }: { focus: Member; setFocus: (member: Member) => void }) { const moduleRows = [{name:"Project Overview",completion:100,time:"18 min",last:"Mon 09:12"},{name:"Local Setup",completion:focus.progress > 55 ? 100 : 68,time:"24 min",last:"Today 10:06"},{name:"Architecture",completion:focus.progress > 65 ? 74 : 18,time:"16 min",last:"Yesterday 16:40"},{name:"APIs & Data Flow",completion:focus.progress > 75 ? 44 : 0,time:"—",last:"Not started"}]; const status = focus.progress >= 60 ? {label:"On track",color:"#8cf7d0"} : focus.progress >= 35 ? {label:"At risk",color:"#f3b56b"} : {label:"Needs attention",color:"#ff7c8c"}; return <><div className="page-heading"><div><p className="eyebrow">ADMIN / TEAM HEALTH</p><h1>Member status</h1><p>See where each developer is in their onboarding journey.</p></div><button className="subtle-btn"><Search size={16} /> Filter members</button></div><div className="members-layout members-stack"><div className="member-table creative-member-list">{members.map((member) => <button key={member.name} className={focus.name === member.name ? "selected" : ""} onClick={() => setFocus(member)}><Avatar initials={member.initials} color={member.color} /><span><strong>{member.name}</strong><small>{member.role}</small></span><div className="member-progress"><span><i style={{ width: `${member.progress}%`, background: member.color }} /></span><b>{member.progress}%</b></div><ChevronRight size={16} /></button>)}</div><div className="member-detail rich-member-detail"><div className="member-detail-head"><Avatar initials={focus.initials} color={focus.color} /><div><h2>{focus.name}</h2><p>{focus.role} · joined 6 days ago</p></div><span className="member-health" style={{ color: status.color, borderColor: `${status.color}80`, background: `${status.color}12` }}><i style={{ background: status.color }} />{status.label}</span></div><div className="member-identity-grid"><span><small>TEAM ID</small><strong>atlas-core</strong></span><span><small>ROLE</small><strong>{focus.role}</strong></span><span><small>LAST ACTIVE</small><strong>{focus.name === "Maya Chen" ? "Today · 10:06" : "Yesterday · 16:40"}</strong></span></div><section className="member-section"><div className="section-head"><div><span className="eyebrow">ONBOARDING PROGRESS</span><h3>Module by module</h3></div><strong className="member-percent">{focus.progress}%</strong></div><div className="member-module-list">{moduleRows.map((row) => <div key={row.name}><span><strong>{row.name}</strong><small>{row.time} · last accessed {row.last}</small></span><b>{row.completion}%</b><i><em style={{ width: `${row.completion}%`, background: focus.color }} /></i></div>)}</div></section><section className="member-section assistant-activity"><div className="section-head"><div><span className="eyebrow">AI ASSISTANT ACTIVITY</span><h3>Questions that shape the Twin</h3></div><BrainCircuit size={17} /></div><div className="activity-stat-grid"><span><strong>24</strong><small>questions asked</small></span><span><strong>7</strong><small>hints used</small></span><span><strong>Auth</strong><small>most frequent topic</small></span></div><p><Sparkles size={14} /> Potential knowledge gap: <b>Authentication and Authorization</b></p></section><section className="member-section engagement-section"><div className="section-head"><div><span className="eyebrow">ACTIVITY & ENGAGEMENT</span><h3>This week’s rhythm</h3></div><Zap size={17} /></div><div className="engagement-bars">{[["Mon",22],["Tue",38],["Wed",18],["Thu",68],["Fri",84],["Sat",28],["Sun",42]].map(([day, value]) => <span key={day}><i style={{ height: `${value}%` }} /><small>{day}</small></span>)}</div><div className="engagement-meta"><span><strong>3</strong> modules completed</span><span><strong>5</strong> day learning streak</span><span><strong>8</strong> tasks completed</span></div></section><div className="admin-summary"><span className="eyebrow">ADMIN SUMMARY</span><p>{focus.name} is progressing {focus.progress >= 60 ? "well overall" : "steadily"} but shows a knowledge gap in authentication and database architecture. Recommend completing the Authentication module before proceeding to Deployment.</p></div></div></div></>; }
function KnowledgeGapReview'''
text, count = re.subn(pattern, replacement, text, count=1)
if count != 1:
    raise RuntimeError('MemberStatus replacement failed')
path.write_text(text)
print('member status exception applied')
